#!/bin/bash
# All mock cases (fixtures regenerated by gen.py), 8 at a time; one line each: case, expected, got, OK|MISMATCH, the
# reason; then TOTAL. Exit 0 only when every case gives its expected verdict. Also: bash -n / sh -n on every script.
M=$(cd "$(dirname "$0")" && pwd); KIT=$(cd $M/.. && pwd); bad=0
for f in $KIT/run.sh $KIT/row/*.sh $KIT/swap/*.sh $M/*.sh; do case $f in *.lamp.sh) continue;; esac; bash -n $f || { echo "SYNTAX $f"; bad=1; }; done
for f in $KIT/row/*.lamp.sh; do cat $KIT/row/common.lamp.sh $f | sh -n || { echo "SYNTAX $f"; bad=1; }; done
for f in $KIT/swap/swap.lamp.sh $KIT/swap/restore.lamp.sh; do cat $KIT/row/common.lamp.sh $KIT/swap/swap-common.lamp.sh $f | sh -n || { echo "SYNTAX $f"; bad=1; }; done
[ $bad = 0 ] && echo "SYNTAX OK (bash -n, sh -n)"
python3 -I $M/gen.py $M/fx || exit 1; rm -rf $M/work
ls $M/fx | xargs -P ${J:-8} -n1 $M/run-case.sh | sort | tee $M/results.txt
ok=$(grep -c ' OK ' $M/results.txt); mm=$(grep -c ' MISMATCH ' $M/results.txt); n=$(ls $M/fx | wc -l | tr -d ' ')
echo "TOTAL $n cases: OK $ok MISMATCH $mm"; [ "$ok" = "$n" ] && [ $bad = 0 ]
